"""Cameroun : géographie physique et humaine (relief, climats, eaux, frontières, toponymes, transports, localités).
Faits rédigés à la main par l'assistant : tout sort en `review`."""
from .cult_kit import rows, table, theme

theme("cm-geo2", "Cameroun : géographie physique et humaine",
      "Comparer avec un atlas du Cameroun (INC, Atlas de l'Afrique), le manuel de géographie du programme MINESEC et une encyclopédie (Larousse, Britannica) ; les altitudes sont arrondies.")

# ------------------------------------------------------------------------------------------------ relief
rows("cm-geo2", "CM", "Relief du Cameroun", [
    (3, "Comment s'appelle le sommet secondaire du massif du mont Cameroun, surnommé le « Petit mont Cameroun » ?", "L'Etinde",
     ["Le Fako", "Le Manengouba", "Le Kupe", "Le Bamboutos"], "L'Etinde (environ 1 700 m) est un cône secondaire du massif ; le sommet principal s'appelle Fako."),
    (4, "Quel nom, issu de la langue des Bakweri, désigne le point culminant du mont Cameroun ?", "Fako",
     ["Etinde", "Oku", "Mandara", "Alantika"], "Fako est le nom local du sommet principal ; il a aussi donné son nom à un département du Sud-Ouest."),
    (2, "À quelle altitude approximative culmine le mont Cameroun ?", "Environ 4 000 m",
     ["Environ 2 000 m", "Environ 3 000 m", "Environ 5 000 m", "Environ 1 500 m"], "Avec un peu plus de 4 000 m, c'est le point culminant du Cameroun et l'un des grands sommets d'Afrique de l'Ouest et du Centre."),
    (4, "Quel est le deuxième sommet du Cameroun par l'altitude, avec un peu plus de 3 000 m ?", "Le mont Oku",
     ["Le mont Manengouba", "Les monts Bamboutos", "Le mont Kupe", "Le Tchabal Mbabo"], "Le mont Oku, dans le Nord-Ouest, dépasse 3 000 m : il vient juste après le mont Cameroun."),
    (1, "Quel type de relief est le mont Cameroun ?", "Un volcan",
     ["Une dune", "Un inselberg granitique", "Une falaise calcaire", "Un plateau gréseux"], "Le mont Cameroun est un volcan actif dont les éruptions ont couvert ses flancs de coulées de lave."),
    (4, "À quel alignement de volcans le mont Cameroun appartient-il ?", "La ligne du Cameroun",
     ["La dorsale médio-atlantique", "Le rift est-africain", "La chaîne de l'Atlas", "L'arc des Cascades"], "La ligne volcanique du Cameroun va du golfe de Guinée vers le nord-est, avec le Manengouba, les Bamboutos et l'Oku."),
    (3, "Quelle île du golfe de Guinée, appartenant à la Guinée équatoriale, se trouve au large de la côte camerounaise ?", "Bioko",
     ["Zanzibar", "Gorée", "Madagascar", "Sainte-Hélène"], "Bioko (ancienne Fernando Poo) est située à une trentaine de kilomètres des côtes camerounaises."),
    (4, "Quel massif volcanique, proche de Nkongsamba, abrite deux lacs de cratère voisins ?", "Le Manengouba",
     ["Le Kupe", "Les monts Rumpi", "Les monts Mandara", "Le Tchabal Mbabo"], "Le massif du Manengouba possède une caldeira avec deux lacs jumeaux, objets de légendes locales."),
    (3, "Quelle altitude moyenne approximative le plateau de l'Adamaoua a-t-il ?", "Environ 1 000 m",
     ["Environ 200 m", "Environ 2 500 m", "Environ 3 500 m", "Au niveau de la mer"], "L'Adamaoua est un haut plateau situé aux alentours de 1 000 à 1 100 m, d'où un climat plus frais que ses voisins."),
    (4, "De qui le nom « Adamaoua » dérive-t-il ?", "Modibo Adama, chef peul du XIXe siècle",
     ["Un roi bamoun du XVIIIe siècle", "Un explorateur allemand", "Un navigateur portugais", "Un missionnaire baptiste"], "Modibo Adama fonda au XIXe siècle l'émirat de Fombina, qu'on appela ensuite Adamawa ou Adamaoua."),
    (3, "Pourquoi surnomme-t-on parfois l'Adamaoua le « château d'eau » du Cameroun ?", "Plusieurs grands cours d'eau y prennent leur source",
     ["Il contient le plus grand lac du pays", "Il reçoit toute la pluie du pays", "Il possède des nappes de pétrole", "Il est entouré par la mer"], "De l'Adamaoua partent des cours d'eau vers l'Atlantique, la Bénoué et le bassin du Tchad."),
    (2, "Que sont les « grassfields » du Cameroun ?", "Des hautes terres herbeuses",
     ["Des forêts de mangroves", "Des plaines inondables du lac Tchad", "Des plantations de bananiers", "Des dunes de sable"], "Le mot anglais désigne les plateaux herbeux et frais de l'Ouest et du Nord-Ouest."),
    (2, "Dans quelles régions trouve-t-on les « grassfields » ?", "Ouest et Nord-Ouest",
     ["Nord et Extrême-Nord", "Sud et Est", "Littoral et Sud-Ouest", "Centre et Sud"], "Les hautes terres de l'Ouest (Bamiléké, Bamoun) et du Nord-Ouest forment les grassfields."),
    (4, "Comment appelle-t-on les vastes plaines inondables du Logone, dans l'Extrême-Nord ?", "Les yaérés",
     ["Les mangroves", "Les grassfields", "Les ergs", "Les wadis"], "Les yaérés sont inondés en saison des pluies : ils nourrissent poissons, oiseaux et troupeaux."),
    (3, "Quel village des monts Mandara est célèbre pour ses pitons volcaniques et ses paysages lunaires ?", "Rhumsiki",
     ["Foumban", "Bafut", "Kribi", "Tibati"], "Rhumsiki (ou Roumsiki), près de Mokolo, est dominé par des culots volcaniques."),
    (3, "Quelle région du Cameroun est surtout formée de plaines, avec la cuvette du lac Tchad ?", "L'Extrême-Nord",
     ["Le Sud-Ouest", "L'Ouest", "Le Littoral", "Le Centre"], "L'Extrême-Nord est largement plat, bordé au nord par le lac Tchad et au sud par les monts Mandara."),
    (5, "Comment appelle-t-on la plaine située autour de Maroua, à l'est des monts Mandara ?", "Le Diamaré",
     ["Le Mbam", "Le Noun", "Le Faro", "Le Lom"], "Le Diamaré est à la fois un département et une plaine au pied des monts Mandara."),
    (4, "Que sont les cases-obus que l'on trouve dans l'Extrême-Nord ?", "Des habitations en terre en forme d'obus",
     ["Des greniers à mil en métal", "Des abris creusés dans la lave", "Des cabanes sur pilotis", "Des tentes en peau"], "Ces cases en terre crue, ornées de motifs en relief, sont l'oeuvre des Mousgoum."),
    (3, "Quel type de roche est la lave refroidie qui couvre les flancs du mont Cameroun ?", "Le basalte",
     ["Le calcaire", "Le grès", "Le marbre", "Le sel gemme"], "Les coulées du mont Cameroun sont faites de basalte, une roche volcanique sombre."),
    (5, "Quel massif de la région de l'Adamaoua, culminant à plus de 2 400 m, est le plus élevé du plateau ?", "Le Tchabal Mbabo",
     ["Le mont Oku", "Le mont Kupe", "Le Manengouba", "Les monts Rumpi"], "Le Tchabal Mbabo (environ 2 460 m) est le point culminant du plateau de l'Adamaoua."),
    (3, "Quelle ville du Sud-Ouest, bâtie sur les flancs du mont Cameroun, est située à environ 900 m d'altitude ?", "Buea",
     ["Limbé", "Tiko", "Kumba", "Mamfe"], "Buea domine la côte, avec un climat plus frais que celui de Limbé."),
    (3, "Quelle ville est le point de départ de la « Course de l'Espoir », qui monte au sommet du mont Cameroun ?", "Buea",
     ["Limbé", "Tiko", "Kumba", "Idenau"], "La course part de Buea et grimpe jusqu'au sommet avant de redescendre."),
])

# ------------------------------------------------------------------------------------------------ climats, saisons, végétation
rows("cm-geo2", "CM", "Climats et saisons du Cameroun", [
    (3, "Combien de saisons compte l'année dans le Sud du Cameroun, au climat de type équatorial ?", "Quatre",
     ["Deux", "Trois", "Cinq", "Six"], "Le Sud a deux saisons des pluies et deux saisons sèches, une longue et une courte de chaque."),
    (2, "Combien de saisons distingue-t-on dans le Nord du Cameroun ?", "Deux, une saison sèche et une saison des pluies",
     ["Quatre", "Trois", "Une seule", "Cinq"], "Dans le Nord, la saison des pluies dure environ de mai à octobre ; le reste de l'année est sec."),
    (3, "Que désigne l'harmattan, qui souffle sur le Nord du Cameroun en saison sèche ?", "Un vent sec et poussiéreux venu du Sahara",
     ["Un courant marin froid", "Une pluie de mousson", "Un fleuve saisonnier", "Une variété de mil"], "L'harmattan souffle surtout de décembre à février, avec une brume de poussière."),
    (4, "Quel vent humide venu de l'océan explique les pluies abondantes sur la côte camerounaise ?", "La mousson",
     ["L'harmattan", "Le mistral", "Le sirocco", "Le blizzard"], "La mousson de l'Atlantique apporte d'énormes quantités de pluie sur le Littoral et le Sud-Ouest."),
    (3, "Quel climat caractérise les hautes terres de l'Ouest, comme Dschang et Bamenda ?", "Un climat tempéré par l'altitude",
     ["Un climat désertique", "Un climat polaire", "Un climat méditerranéen", "Un climat sahélien"], "L'altitude donne aux grassfields des températures plus douces et des nuits fraîches."),
    (2, "Quelle végétation couvre l'essentiel du Sud et de l'Est du Cameroun ?", "La forêt dense équatoriale",
     ["La toundra", "La steppe désertique", "La taïga", "Les dunes"], "Le Sud et l'Est sont couverts de forêt dense humide, riche en bois précieux."),
    (2, "Quelle formation végétale borde l'estuaire du Wouri et une partie de la côte ?", "La mangrove",
     ["La taïga", "La steppe", "La prairie alpine", "La toundra"], "Les palétuviers de la mangrove poussent dans l'eau salée à l'embouchure des fleuves."),
    (3, "Quelle végétation domine l'Extrême-Nord ?", "La steppe et la savane à épineux",
     ["La forêt dense", "La mangrove", "La toundra", "La forêt de bambous"], "L'Extrême-Nord, de climat sahélien, est couvert d'une steppe parsemée d'acacias."),
    (3, "Quelle végétation caractérise l'Adamaoua ?", "La savane arborée",
     ["La mangrove", "La toundra", "Le désert", "La forêt de conifères"], "Sur le plateau, des herbes hautes et des arbres épars forment une savane."),
    (4, "Quel climat caractérise l'Adamaoua et la région du Nord, entre le Sud humide et le Sahel sec ?", "Un climat soudanien, avec une saison des pluies marquée",
     ["Un climat désertique toute l'année", "Un climat polaire", "Un climat océanique sans saison sèche", "Un climat méditerranéen"], "Plus on monte vers le nord, plus la saison sèche est longue."),
    (4, "Quelle région est la plus arrosée du Cameroun, à cause de la mousson et du relief du mont Cameroun ?", "Le Sud-Ouest",
     ["L'Extrême-Nord", "Le Nord", "L'Adamaoua", "L'Est"], "Au pied du mont Cameroun, certaines stations reçoivent plus de 8 m de pluie par an."),
    (1, "Quelle région du Cameroun est la plus sèche et la plus chaude ?", "L'Extrême-Nord",
     ["Le Sud", "Le Littoral", "L'Ouest", "Le Sud-Ouest"], "Au bord du Sahel, l'Extrême-Nord reçoit peu de pluie et connaît de grosses chaleurs."),
    (2, "Pendant quelle saison l'harmattan souffle-t-il surtout sur le Nord du Cameroun ?", "La saison sèche",
     ["La saison des pluies", "Le printemps", "Toute l'année sans interruption", "Le mois de juillet seulement"], "Il accompagne la saison sèche, avec des matins frais et du vent."),
    (3, "À quoi le « Mongo ma Loba » fait-il référence dans la langue bakweri ?", "Au mont Cameroun",
     ["Au lac Nyos", "Au fleuve Wouri", "Au plateau de l'Adamaoua", "Au mont Oku"], "« Mongo ma Loba » désigne le mont Cameroun, souvent traduit par « montagne des dieux »."),
    (3, "Pourquoi le climat de Yaoundé est-il un peu plus frais que celui de Douala ?", "Parce que la ville est plus haute, vers 750 m",
     ["Parce qu'elle est plus au nord", "Parce qu'elle est au bord de la mer", "Parce qu'elle est dans le désert", "Parce qu'elle est dans une vallée glacée"], "Yaoundé est sur un plateau, tandis que Douala est au niveau de l'estuaire."),
    (5, "Comment appelle-t-on la courte saison sèche de l'été (vers juillet-août) dans le Sud équatorial ?", "La petite saison sèche",
     ["La saison de l'harmattan", "La saison des brumes", "La saison des cyclones", "La longue saison sèche"], "Dans le Sud, la petite saison sèche s'intercale entre la petite et la grande saison des pluies."),
])

# ------------------------------------------------------------------------------------------------ fleuves, lacs, chutes
rows("cm-geo2", "CM", "Fleuves, lacs et chutes", [
    (4, "Quel fleuve du Centre-Sud traverse la ville de Mbalmayo ?", "Le Nyong",
     ["La Sanaga", "Le Wouri", "Le Ntem", "Le Mungo"], "Le Nyong coule d'est en ouest avant de se jeter dans l'Atlantique."),
    (5, "Quels deux cours d'eau forment la Sanaga en se rejoignant ?", "Le Lom et le Djérem",
     ["Le Mbam et le Noun", "Le Wouri et le Nkam", "La Bénoué et le Faro", "Le Logone et la Vina"], "La Sanaga naît de la réunion du Lom et du Djérem, dans la zone de l'Adamaoua et de l'Est."),
    (4, "Quel grand affluent de la Sanaga draine une partie de l'Ouest et du Centre ?", "Le Mbam",
     ["Le Dja", "Le Faro", "Le Nyong", "Le Mungo"], "Le Mbam, grossi par le Noun, rejoint la Sanaga."),
    (4, "Quelle ville de l'Ouest est située au bord du Noun ?", "Foumban",
     ["Bafoussam", "Dschang", "Mbouda", "Bandjoun"], "Foumban, capitale du royaume Bamoun, se trouve sur la rive du Noun."),
    (4, "Quels deux cours d'eau se rejoignent près de Kousséri et de N'Djamena avant de rejoindre le lac Tchad ?", "Le Logone et le Chari",
     ["La Bénoué et le Faro", "Le Wouri et la Sanaga", "Le Mayo-Kani et le Mayo-Tsanaga", "La Vina et le Mbam"], "Le Logone se jette dans le Chari à hauteur de N'Djamena ; le Chari rejoint ensuite le lac Tchad."),
    (2, "Quelle capitale africaine se trouve juste de l'autre côté de la frontière, face à Kousséri ?", "N'Djamena",
     ["Bangui", "Libreville", "Malabo", "Brazzaville"], "Kousséri, dans l'Extrême-Nord, est séparée de N'Djamena par le fleuve."),
    (3, "Dans quel grand fleuve africain la Bénoué se jette-t-elle, au Nigeria ?", "Le Niger",
     ["Le Congo", "Le Nil", "Le Sénégal", "Le Zambèze"], "La Bénoué est le principal affluent du Niger, qu'elle rejoint à Lokoja."),
    (3, "Dans quoi le Chari, grossi par le Logone, se jette-t-il ?", "Le lac Tchad",
     ["L'océan Atlantique", "Le Niger", "Le Nil", "Le golfe de Guinée"], "Le Chari et le Logone alimentent le lac Tchad."),
    (3, "Vers quel océan coule la Sanaga ?", "L'océan Atlantique",
     ["L'océan Indien", "L'océan Arctique", "La mer Rouge", "La Méditerranée"], "La Sanaga se jette dans l'Atlantique, en aval d'Édéa."),
    (3, "Vers quel grand fleuve coulent les eaux de la Sangha, qui longe le Sud-Est du Cameroun ?", "Le Congo",
     ["Le Niger", "Le Nil", "Le Zambèze", "Le Chari"], "La Sangha est un affluent du fleuve Congo."),
    (4, "Quel lac de cratère près de Kumba abrite de nombreux poissons qu'on ne trouve nulle part ailleurs ?", "Le lac Barombi Mbo",
     ["Le lac Nyos", "Le lac Monoun", "Le lac Oku", "Le lac Bamendjing"], "Le Barombi Mbo est célèbre pour ses poissons endémiques de la famille des cichlidés."),
    (5, "En quelle année un dégagement de gaz a-t-il fait des morts au lac Monoun, deux ans avant la catastrophe de Nyos ?", "1984",
     ["1980", "1982", "1986", "1990"], "Le lac Monoun, dans l'Ouest, a rejeté du gaz carbonique en 1984, faisant 37 victimes."),
    (3, "Que constate-t-on depuis la seconde moitié du XXe siècle à propos du lac Tchad ?", "Sa surface a fortement diminué",
     ["Elle a triplé", "Il a été comblé", "Il est devenu une mer", "Il a changé de continent"], "Le lac Tchad s'est beaucoup réduit à cause de la sécheresse et des prélèvements d'eau."),
    (4, "Quelle organisation, créée en 1964, rassemble des pays riverains du lac Tchad ?", "La Commission du bassin du lac Tchad",
     ["L'Autorité du bassin du Niger", "La CEEAC", "La COMIFAC", "La CEMAC"], "Cette commission, dont le siège est à N'Djamena, coordonne la gestion du lac."),
    (4, "Quelles chutes de la région du Littoral, sur le Nkam, ont servi de décor à un célèbre film sur Tarzan ?", "Les chutes d'Ekom-Nkam",
     ["Les chutes de la Lobé", "Les chutes de la Vina", "Les chutes de Nachtigal", "Les chutes d'Édéa"], "Les chutes d'Ekom-Nkam, près de Melong, apparaissent dans le film Greystoke (1984)."),
    (3, "Quelles chutes se jettent directement dans l'océan Atlantique, à quelques kilomètres de Kribi ?", "Les chutes de la Lobé",
     ["Les chutes d'Ekom-Nkam", "Les chutes d'Édéa", "Les chutes de la Vina", "Les chutes de la Métché"], "La Lobé tombe dans l'océan : un site rare, car peu de chutes dans le monde finissent dans la mer."),
    (4, "Quel explorateur allemand donne son nom aux chutes et au barrage de Nachtigal sur la Sanaga ?", "Gustav Nachtigal",
     ["Heinrich Barth", "Georg Zenker", "Eugen Zintgraff", "Hermann von Wissmann"], "Gustav Nachtigal signa en 1884 les traités qui ouvrirent la voie au protectorat allemand."),
    (3, "Sur quel fleuve se trouve la ville de Garoua, port fluvial navigable en saison des pluies ?", "La Bénoué",
     ["La Sanaga", "Le Logone", "Le Wouri", "Le Nyong"], "Garoua est un port fluvial de la Bénoué, accessible aux bateaux quand les eaux sont hautes."),
    (4, "Quel est le principal cours d'eau de la ville de Douala ?", "Le Wouri",
     ["Le Nyong", "Le Ntem", "La Sanaga", "La Bénoué"], "Le Wouri forme l'estuaire sur lequel s'est développée la ville."),
    (4, "Quelle rivière a donné son nom au département du Moungo ?", "Le Mungo",
     ["Le Dibamba", "Le Mbam", "Le Faro", "Le Noun"], "Le département du Moungo porte le nom de la rivière Mungo."),
    (2, "Que signifie « mayo » dans des noms comme Mayo-Danay ou Mayo-Kani ?", "Rivière ou cours d'eau",
     ["Montagne", "Village", "Marché", "Forêt"], "Le mot vient de la langue peule (le fulfulde) et désigne un cours d'eau, souvent saisonnier."),
    (4, "Quel fleuve du Cameroun prend sa source près d'Abong-Mbang, dans l'Est, et traverse Akonolinga ?", "Le Nyong",
     ["Le Ntem", "Le Mungo", "La Bénoué", "Le Dja"], "Le Nyong naît dans l'Est, traverse Abong-Mbang, Akonolinga puis Mbalmayo."),
    (3, "Quel lac de retenue de l'Adamaoua est formé sur le Djérem ?", "Le lac Mbakaou",
     ["Le lac Bamendjing", "Le lac Nyos", "Le lac Ossa", "Le lac Monoun"], "Le lac de Mbakaou est un réservoir de la Sanaga supérieure, dans l'Adamaoua."),
    (3, "Sur quel cours d'eau est établi le lac de retenue de Bamendjing, dans l'Ouest ?", "Le Noun",
     ["La Bénoué", "Le Logone", "Le Nyong", "Le Wouri"], "Le réservoir de Bamendjing régularise le débit du Noun."),
])

# ------------------------------------------------------------------------------------------------ frontières et voisins
rows("cm-geo2", "CM", "Frontières et voisins du Cameroun", [
    (3, "Quel pays voisin partage avec le Cameroun la plus longue frontière ?", "Le Nigeria",
     ["Le Tchad", "La Centrafrique", "Le Congo", "Le Gabon"], "La frontière avec le Nigeria dépasse 1 900 km, de l'Atlantique au lac Tchad."),
    (5, "Quel pays voisin partage avec le Cameroun la plus courte frontière terrestre ?", "La Guinée équatoriale",
     ["Le Gabon", "Le Congo", "Le Tchad", "La Centrafrique"], "La frontière avec la Guinée équatoriale ne dépasse guère 180 km."),
    (1, "De quel pays voisin du Cameroun Bangui est-elle la capitale ?", "La République centrafricaine",
     ["Le Tchad", "Le Gabon", "Le Congo", "Le Nigeria"], "Bangui, sur l'Oubangui, est la capitale de la République centrafricaine."),
    (2, "Dans quel pays voisin du Cameroun se trouve la ville de Libreville ?", "Le Gabon",
     ["Le Congo", "La Guinée équatoriale", "Le Tchad", "Le Nigeria"], "Libreville est la capitale du Gabon, au sud du Cameroun."),
    (3, "Quel pays voisin du Cameroun a pour capitale Malabo ?", "La Guinée équatoriale",
     ["Le Gabon", "Le Congo", "Le Tchad", "La Centrafrique"], "Malabo est située sur l'île de Bioko, au large du Cameroun."),
    (3, "Quelle ville de l'Est marque le passage de la route de Bertoua vers Bangui ?", "Garoua-Boulaï",
     ["Kyé-Ossi", "Ekok", "Moloundou", "Kousséri"], "Garoua-Boulaï est un point de passage vers la RCA sur l'axe Bertoua-Bangui."),
    (4, "Quel poste frontière du Sud est proche de la jonction avec le Gabon et la Guinée équatoriale ?", "Kyé-Ossi",
     ["Garoua-Boulaï", "Ekok", "Kousséri", "Idenau"], "Kyé-Ossi, dans la Vallée-du-Ntem, est un poste frontière avec la Guinée équatoriale, près du Gabon."),
    (4, "Ekok, sur la route de Mamfe, est un poste frontière avec quel pays ?", "Le Nigeria",
     ["Le Gabon", "Le Tchad", "Le Congo", "La Centrafrique"], "Ekok est à la frontière du Sud-Ouest, face à l'État nigérian de Cross River."),
    (4, "Moloundou, dans l'Est, est située près de la frontière avec quel pays ?", "Le Congo",
     ["Le Gabon", "La Centrafrique", "Le Tchad", "Le Nigeria"], "Moloundou est une localité de Boumba-et-Ngoko, proche de la frontière du Congo."),
    (4, "Dans quelle région administrative se situe la péninsule de Bakassi ?", "Le Sud-Ouest",
     ["Le Littoral", "Le Sud", "Le Nord-Ouest", "Le Centre"], "Bakassi, dans le département de Ndian, borde le golfe de Guinée."),
    (4, "Quelle juridiction siégeant à La Haye a rendu en 2002 un arrêt sur la frontière entre le Cameroun et le Nigeria ?", "La Cour internationale de Justice",
     ["La Cour pénale internationale", "Le Tribunal international du droit de la mer", "La Cour africaine des droits de l'homme", "La Cour de justice de la CEDEAO"], "L'arrêt de la CIJ, rendu le 10 octobre 2002, a précisé le tracé de la frontière."),
    (5, "Quel accord signé en 2006 près de New York a organisé le retrait nigérian de Bakassi ?", "L'accord de Greentree",
     ["L'accord d'Évian", "Les accords de Camp David", "L'accord de Lomé", "L'accord d'Arusha"], "L'accord de Greentree a été conclu sous l'égide de l'ONU, avec le transfert effectif en 2008."),
    (2, "Dans quelle partie de l'Afrique se situe le Cameroun ?", "À la jonction de l'Afrique de l'Ouest et de l'Afrique centrale",
     ["Dans le Maghreb", "En Afrique australe", "Dans la Corne de l'Afrique", "Dans les îles de l'océan Indien"], "Le Cameroun est parfois appelé « charnière » entre l'Ouest et le Centre de l'Afrique."),
    (2, "Que dit-on de la position du Cameroun par rapport à l'équateur ?", "Il est entièrement dans l'hémisphère nord",
     ["Il est traversé par l'équateur au sud", "Il est entièrement dans l'hémisphère sud", "L'équateur passe par Kribi", "L'équateur passe par Douala"], "Le pays s'étend du sud, vers 2° de latitude nord, jusqu'au lac Tchad."),
    (3, "Quelle est la superficie approximative du Cameroun ?", "Environ 475 000 km²",
     ["Environ 150 000 km²", "Environ 250 000 km²", "Environ 750 000 km²", "Environ 1 000 000 km²"], "Le Cameroun couvre à peu près 475 000 km²."),
    (3, "Quel pays a une frontière commune avec le Cameroun dans le Sud-Est et pour capitale Brazzaville ?", "Le Congo",
     ["Le Gabon", "La République démocratique du Congo", "La Centrafrique", "Le Tchad"], "Le Congo-Brazzaville touche le Sud-Est du Cameroun ; la RDC, elle, n'a pas de frontière avec lui."),
    (4, "Parmi ces pays, lequel n'a PAS de frontière commune avec le Cameroun ?", "Le Niger",
     ["Le Tchad", "La Centrafrique", "Le Nigeria", "Le Gabon"], "Le Niger touche le lac Tchad mais n'a pas de frontière terrestre avec le Cameroun."),
    (4, "Parmi ces pays, lequel n'a PAS de frontière terrestre avec le Cameroun ?", "La République démocratique du Congo",
     ["Le Congo", "La Guinée équatoriale", "Le Tchad", "La Centrafrique"], "La RDC est séparée du Cameroun par la Centrafrique et le Congo."),
    (4, "Quelle région touche à la fois la Centrafrique et le Congo ?", "L'Est",
     ["L'Adamaoua", "Le Sud", "Le Nord", "Le Centre"], "La région de l'Est borde la RCA et le Congo."),
    (3, "Quelle région du Cameroun borde le Gabon ?", "Le Sud",
     ["Le Centre", "Le Littoral", "L'Ouest", "Le Sud-Ouest"], "Le Sud a des frontières avec le Gabon, la Guinée équatoriale et le Congo."),
    (4, "Parmi ces régions, laquelle n'a ni côte ni frontière internationale ?", "L'Ouest",
     ["Le Sud", "L'Est", "L'Extrême-Nord", "Le Nord-Ouest"], "L'Ouest est entièrement entouré d'autres régions camerounaises."),
    (3, "Quelle région du Cameroun a la plus grande superficie ?", "L'Est",
     ["Le Centre", "L'Extrême-Nord", "Le Littoral", "L'Ouest"], "L'Est, avec ses grandes forêts, est la région la plus vaste du pays."),
    (4, "Quelle région du Cameroun a la plus petite superficie ?", "L'Ouest",
     ["Le Littoral", "Le Nord-Ouest", "Le Sud-Ouest", "Le Centre"], "L'Ouest, malgré sa forte densité de peuplement, est la plus petite région du pays."),
    (1, "Quelle région est la plus au nord du Cameroun ?", "L'Extrême-Nord",
     ["Le Nord", "L'Adamaoua", "Le Nord-Ouest", "L'Est"], "L'Extrême-Nord s'étend jusqu'au lac Tchad."),
    (1, "Quelle région est la plus au sud du Cameroun ?", "Le Sud",
     ["Le Centre", "Le Sud-Ouest", "Le Littoral", "L'Est"], "Le Sud touche le Gabon, la Guinée équatoriale et le Congo."),
    (1, "Quelle région est la plus à l'est du Cameroun ?", "L'Est",
     ["Le Nord", "Le Centre", "L'Adamaoua", "Le Sud"], "L'Est borde la Centrafrique."),
    (2, "Quelle région occupe le plateau qui relie le Nord et le Sud du Cameroun ?", "L'Adamaoua",
     ["Le Littoral", "L'Ouest", "Le Sud-Ouest", "Le Sud"], "L'Adamaoua est la région-charnière entre le Sud forestier et le Nord de savane."),
    (3, "Combien de régions du Cameroun ont une façade maritime ?", "Trois",
     ["Deux", "Quatre", "Cinq", "Une seule"], "Le Sud-Ouest, le Littoral et le Sud bordent l'océan Atlantique."),
    (3, "Laquelle de ces régions ne borde pas l'océan Atlantique ?", "L'Ouest",
     ["Le Sud", "Le Littoral", "Le Sud-Ouest"], "Seules les régions du Sud, du Littoral et du Sud-Ouest ont une façade maritime."),
    (2, "Dans quelle direction se trouve le Nigeria par rapport au Cameroun ?", "À l'ouest",
     ["À l'est", "Au sud", "Au nord-est", "Au sud-est"], "Le Nigeria est le grand voisin de l'Ouest du Cameroun."),
    (2, "Dans quelle direction se trouve la Centrafrique par rapport au Cameroun ?", "À l'est",
     ["À l'ouest", "Au sud", "Au nord-ouest", "Au sud-ouest"], "La RCA borde l'Est du Cameroun."),
    (2, "Dans quelle direction se trouve le Gabon par rapport au Cameroun ?", "Au sud",
     ["Au nord", "À l'est", "Au nord-est", "À l'ouest"], "Le Gabon borde le Sud du Cameroun."),
    (3, "Dans quelle partie du pays se trouve le lac Tchad ?", "Dans le Nord, à l'extrémité de l'Extrême-Nord",
     ["Dans le Sud-Ouest", "Dans le Centre", "Dans l'Est", "Dans le Littoral"], "Le lac Tchad borde l'extrémité nord du pays."),
    (4, "Quelles régions du Cameroun bordent le Nigeria du sud au nord ?", "Sud-Ouest, Nord-Ouest, Adamaoua, Nord et Extrême-Nord",
     ["Sud, Centre, Adamaoua et Nord", "Littoral, Ouest, Nord et Est", "Sud-Ouest, Littoral, Centre et Est", "Ouest, Centre, Nord et Extrême-Nord"], "La frontière avec le Nigeria suit ces cinq régions, de l'océan au lac Tchad."),
])

# ------------------------------------------------------------------------------------------------ toponymes et origines de noms
rows("cm-geo2", "CM", "Noms de lieux du Cameroun", [
    (2, "Quel animal marin a donné son nom au Cameroun, d'après les Portugais ?", "La crevette",
     ["Le lamantin", "Le crocodile", "Le requin", "Le pélican"], "Les Portugais virent tant de crevettes dans le Wouri qu'ils l'appelèrent « Rio dos Camarões »."),
    (1, "De quelle langue vient le mot « Camarões », à l'origine du nom Cameroun ?", "Le portugais",
     ["L'allemand", "L'anglais", "L'arabe", "Le latin"], "Camarões signifie « crevettes » en portugais."),
    (2, "Que signifie « Rio dos Camarões », nom donné au Wouri par les marins portugais ?", "La rivière des crevettes",
     ["Le fleuve des éléphants", "La rivière des caïmans", "Le fleuve des pirogues", "La rivière des mangroves"], "Le nom a donné « Cameroun » en français et « Cameroon » en anglais."),
    (1, "Comment les Allemands écrivaient-ils le nom du pays à l'époque coloniale ?", "Kamerun",
     ["Cameroons", "Camarones", "Kammerun", "Kamarun"], "Pendant le protectorat (1884-1916), le territoire s'appelait Kamerun."),
    (2, "Comment appelait-on la partie du Cameroun administrée par le Royaume-Uni après la Première Guerre mondiale ?", "Les Cameroons britanniques",
     ["Le Cameroun oriental", "La Kamerun-Nord", "Le Togoland", "Le Biafra"], "Les British Cameroons étaient gérés depuis le Nigeria voisin."),
    (3, "Quel nom portait la ville de Limbé avant 1982 ?", "Victoria",
     ["Buea", "Bota", "Kumba", "Tiko"], "La ville fut fondée en 1858 et baptisée en l'honneur de la reine Victoria."),
    (4, "Qui fonda en 1858 la ville de Victoria, aujourd'hui Limbé ?", "Alfred Saker, missionnaire baptiste",
     ["Gustav Nachtigal", "David Livingstone", "Eugen Zintgraff", "Rudolf Manga Bell"], "Alfred Saker y installa une colonie de chrétiens baptistes ; la ville prit le nom de la reine britannique."),
    (3, "Quelle ville a été fondée par les Allemands à la fin des années 1880 sous le nom de Jaunde ?", "Yaoundé",
     ["Bertoua", "Garoua", "Buea", "Bafoussam"], "Georg Zenker y installa un poste à la fin des années 1880 ; Jaunde est la graphie allemande de Yaoundé."),
    (3, "De quel peuple le nom de Yaoundé est-il une déformation ?", "Les Ewondo",
     ["Les Bassa", "Les Bamoun", "Les Mousgoum", "Les Bakweri"], "Yaoundé vient de « Ewondo », par l'intermédiaire de la graphie allemande Jaunde."),
    (2, "De quel peuple le nom de Douala est-il tiré ?", "Les Duala",
     ["Les Bamoun", "Les Ewondo", "Les Kirdi", "Les Baka"], "La ville s'est développée sur la terre des Duala, au bord du Wouri."),
    (4, "Quelle ville du flanc du mont Cameroun a été le siège de l'administration coloniale allemande au début du XXe siècle ?", "Buea",
     ["Limbé", "Tiko", "Mutengene", "Muyuka"], "Les Allemands s'installèrent à Buea en 1901, sur les pentes du volcan, à l'altitude et au climat plus doux."),
    (5, "Quel nom portait Kousséri à l'époque coloniale française ?", "Fort-Foureau",
     ["Fort-Lamy", "Fort-Archambault", "Fort-Crampel", "Fort-Rousset"], "Fort-Foureau fut renommé Kousséri ; Fort-Lamy est l'ancien nom de N'Djamena."),
    (4, "Quel ancien nom portait N'Djamena, capitale du Tchad voisin ?", "Fort-Lamy",
     ["Fort-Foureau", "Léopoldville", "Salisbury", "Coquilhatville"], "Fort-Lamy fut rebaptisée N'Djamena en 1973."),
    (4, "Quel ancien nom portait Bioko ?", "Fernando Poo",
     ["Annobón", "Corisco", "Gorée", "Marie-Galante"], "L'île porta le nom du navigateur portugais Fernão do Pó."),
    (3, "Quel navigateur portugais est traditionnellement associé à la découverte de l'estuaire du Wouri, vers 1472 ?", "Fernão do Pó",
     ["Vasco de Gama", "Bartolomeu Dias", "Henri le Navigateur", "Magellan"], "Fernão do Pó est lié à « Rio dos Camarões » ; l'île de Bioko a longtemps porté son nom."),
    (4, "Quel nom a le fleuve que les cartes portugaises appelaient « Rio dos Camarões » ?", "Le Wouri",
     ["Le Nyong", "Le Ntem", "La Sanaga", "Le Dibamba"], "Les Portugais du XVe siècle avaient baptisé l'estuaire du Wouri, d'où vient le nom du pays."),
])

# ------------------------------------------------------------------------------------------------ transports : rail, routes, ports, aéroports
rows("cm-geo2", "CM", "Transports au Cameroun", [
    (3, "Quelle société exploite le réseau ferroviaire camerounais depuis la concession de 1999 ?", "Camrail",
     ["Camair", "Sodecoton", "Camtel", "Hydro-Mekin"], "Camrail gère les lignes Douala-Yaoundé, Yaoundé-Ngaoundéré et Douala-Kumba."),
    (4, "En quelle année la voie ferrée du Transcamerounais a-t-elle atteint Ngaoundéré ?", "1974",
     ["1960", "1965", "1982", "1990"], "Le tronçon Yaoundé-Ngaoundéré, ouvert en 1974, a prolongé la ligne venue de Douala."),
    (3, "Quelle ville située sur la Sanaga est une étape de la ligne de chemin de fer Douala-Yaoundé ?", "Édéa",
     ["Kribi", "Limbé", "Bafoussam", "Bertoua"], "Le train de Douala à Yaoundé passe par Édéa, sur la Sanaga."),
    (4, "Quelle route nationale relie Douala à Yaoundé ?", "La N3",
     ["La N1", "La N2", "La N7", "La N11"], "L'axe Douala-Yaoundé, le plus fréquenté du pays, porte le numéro N3."),
    (5, "Quelle route nationale relie Yaoundé à Ebolowa et à la frontière de Kyé-Ossi ?", "La N2",
     ["La N3", "La N1", "La N9", "La N12"], "La N2 rejoint Ebolowa, Ambam et Kyé-Ossi, au sud du pays."),
    (4, "Quelle grande route nationale relie Yaoundé à Ngaoundéré, puis à Garoua et à l'Extrême-Nord ?", "La N1",
     ["La N3", "La N2", "La N5", "La N8"], "La N1 est la grande route qui relie le Sud au Nord du pays."),
    (4, "Quel nom porte la route circulaire du Nord-Ouest autour de Bamenda ?", "La Ring Road",
     ["La Corniche", "Le Transcam", "La Route de l'Unité", "La Ceinture du Mandara"], "La Ring Road relie Bamenda à Wum, Nkambé, Kumbo et Ndop."),
    (2, "Quel est le principal port maritime du Cameroun ?", "Douala",
     ["Kribi", "Limbé", "Tiko", "Campo"], "Le port de Douala, sur l'estuaire du Wouri, est le premier port du pays."),
    (3, "Quel pays enclavé voisin utilise beaucoup le port de Douala pour ses échanges ?", "Le Tchad",
     ["Le Gabon", "La Guinée équatoriale", "Le Nigeria", "Le Congo"], "Douala sert de porte d'entrée maritime au Tchad et à la Centrafrique."),
    (4, "Quel est le code IATA de l'aéroport international de Douala ?", "DLA",
     ["NSI", "GOU", "MVR", "YAO"], "DLA identifie l'aéroport international de Douala."),
    (4, "Quel est le code IATA de l'aéroport international de Yaoundé-Nsimalen ?", "NSI",
     ["DLA", "GOU", "BFX", "NGE"], "NSI renvoie à Nsimalen, au sud de la capitale."),
    (5, "Quel est le code IATA de l'aéroport de Garoua ?", "GOU",
     ["DLA", "NSI", "MVR", "BPC"], "GOU désigne l'aéroport de Garoua, dans le Nord."),
    (2, "Quel aéroport international dessert la capitale politique, Yaoundé ?", "Nsimalen",
     ["Salak", "Baleng", "Tiko", "Bota"], "L'aéroport de Yaoundé-Nsimalen est à une quinzaine de kilomètres du centre."),
    (4, "Dans quelle ville se trouve l'aéroport de Salak ?", "Maroua",
     ["Garoua", "Ngaoundéré", "Bertoua", "Kousséri"], "Maroua-Salak est l'aéroport de l'Extrême-Nord."),
    (3, "Quel port en eau profonde du Sud du Cameroun, aménagé dans les années 2010, complète celui de Douala ?", "Le port de Kribi",
     ["Le port de Limbé", "Le port de Garoua", "Le port d'Édéa", "Le port de Campo"], "Le port en eau profonde de Kribi, construit à une trentaine de kilomètres au sud de la ville, sert surtout au bois, au vrac et aux conteneurs."),
    (4, "Quelle ville de l'Extrême-Nord est la porte d'entrée routière vers N'Djamena ?", "Kousséri",
     ["Maroua", "Mora", "Yagoua", "Mokolo"], "Kousséri est face à la capitale tchadienne."),
    (3, "Quelle ville possède le principal port fluvial du Nord du Cameroun ?", "Garoua",
     ["Maroua", "Ngaoundéré", "Kousséri", "Yagoua"], "Garoua, sur la Bénoué, est un port fluvial, utile surtout en saison des pluies."),
    (4, "Quelle liaison ferroviaire historique allait de Douala à Nkongsamba, au pied du Manengouba ?", "La ligne du Nord (Nordbahn)",
     ["La ligne de l'Est", "La ligne du Mandara", "La ligne de la Bénoué", "La ligne de Ngaoundéré"], "Cette ligne, construite par les Allemands, a été ouverte en 1911 pour évacuer les produits de la région."),
])

